interface MapsWindow extends Window {
  google?: { maps?: GoogleMapsNamespace };
  gm_authFailure?: () => void;
  __aureformGoogleMapsLoaderV1?: LoaderState;
  __aureformGoogleMapsReadyV1?: () => void;
